<template><section class="support-screen"><header><button aria-label="프로필로 돌아가기" @click="router.push('/profile')">‹</button><h1>고객센터</h1></header><nav aria-label="고객센터 메뉴"><button :class="{active:tab==='write'}" @click="tab='write'">문의하기</button><button :class="{active:tab==='history'}" @click="tab='history';load()">내 문의</button></nav><main><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="error" class="error" role="alert">{{error}}</p><form v-if="tab==='write'" @submit.prevent="submit"><label>문의 유형<select v-model="category"><option v-for="(name,key) in categories" :value="key" :key="key">{{name}}</option></select></label><label class="question-label">문의 내용<textarea v-model="question" maxlength="1000" required placeholder="불편한 점이나 궁금한 내용을 적어 주세요."/></label><p class="counter">{{question.length}} / 1,000</p><p class="help">관리자가 확인 후 답변드립니다. 비밀번호나 결제정보는 적지 마세요.</p><button class="submit" :disabled="busy||!question.trim()">{{busy?'접수 중…':'문의 접수하기'}}</button></form><section v-else class="history"><div class="history-heading"><h2>최근 문의 10건</h2><button :disabled="loading" @click="load">새로고침</button></div><p v-if="loading">불러오는 중…</p><p v-else-if="!inquiries.length" class="empty">아직 접수한 문의가 없어요.</p><article v-for="item in inquiries" :key="item.id"><div class="inquiry-heading"><strong>{{categories[item.category]||'문의'}}</strong><span>{{statuses[item.status]||item.status}}</span></div><time>{{new Date(item.createdAt).toLocaleString('ko-KR')}}</time><p class="question">{{item.question}}</p><div v-if="item.adminReply" class="reply"><strong>고객센터 답변</strong><p>{{item.adminReply}}</p></div><p v-else class="help">답변을 기다리고 있어요.</p></article></section><footer><details><summary>이용약관</summary><TermsText type="terms"/></details><details><summary>개인정보 안내</summary><TermsText type="privacy"/></details><p>Dating App · {{version}} · 테스트 서비스</p></footer></main></section></template>
<script setup>
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import api from '../../api/api';import TermsText from '../../components/TermsText.vue';import packageJson from '../../../package.json';
const router=useRouter(),version=packageJson.version,tab=ref('write'),category=ref('GENERAL'),question=ref(''),inquiries=ref([]),loading=ref(false),busy=ref(false),error=ref(''),message=ref('');const categories={GENERAL:'일반 문의',LOGIN:'로그인·회원가입',REVIEW:'사진·프로필 심사',PROFILE:'프로필 관리',PAYMENT:'크레딧·구매',SAFETY:'신고·이용 제한'},statuses={OPEN:'접수 완료',IN_PROGRESS:'확인 중',RESOLVED:'답변 완료',CLOSED:'종결'};
async function load(){if(loading.value)return;loading.value=true;error.value='';try{inquiries.value=(await api.get('/support/inquiries/me')).data;}catch{error.value='문의 내역을 불러오지 못했어요.';}finally{loading.value=false;}}
async function submit(){if(busy.value||!question.value.trim())return;busy.value=true;error.value='';message.value='';try{await api.post('/support/inquiries',{category:category.value,channel:'SUPPORT_CENTER',question:question.value.trim()});question.value='';message.value='문의가 접수되었습니다. 답변은 내 문의와 알림함에서 확인해 주세요.';tab.value='history';await load();}catch(e){error.value=e.response?.data?.message||'문의 접수 결과를 확인하지 못했어요. 내 문의에서 먼저 확인해 주세요.';}finally{busy.value=false;}}
onMounted(load);
</script>
<style scoped>
.support-screen{position:fixed;inset:0;z-index:90;display:flex;flex-direction:column;background:white;color:#40332b;height:100dvh;width:100%;overflow:hidden}.support-screen header{display:flex;align-items:center;gap:12px;padding:calc(12px + env(safe-area-inset-top)) 16px 12px;border-bottom:1px solid #f1e9e3;flex:none}.support-screen h1{font-size:20px;margin:0}.support-screen button{font:inherit;cursor:pointer}.support-screen header button{border:0;background:#fff4ec;color:#a65f43;width:40px;height:40px;border-radius:50%;font-size:28px}.support-screen nav{display:flex;flex:none;border-bottom:1px solid #f1e9e3}.support-screen nav button{flex:1;border:0;border-bottom:2px solid transparent;background:white;padding:16px;color:#9b8a7e}.support-screen nav .active{color:#b66b4d;border-color:#ca7955;font-weight:700}.support-screen main{flex:1;overflow:auto;padding:24px 20px calc(24px + env(safe-area-inset-bottom));min-height:0}.support-screen form{display:flex;flex-direction:column;min-height:calc(100dvh - 260px)}.support-screen label{display:grid;gap:10px;font-size:13px;margin-bottom:22px}.support-screen select,.support-screen textarea{width:100%;font:inherit;border:1px solid #eadfd7;border-radius:12px;padding:14px;background:#fffcfa;box-sizing:border-box;color:inherit}.question-label{flex:1;display:flex!important;flex-direction:column}.support-screen textarea{flex:1;min-height:200px;resize:vertical;line-height:1.7}.counter{text-align:right;margin:-14px 0 12px;color:#a9988b;font-size:11px}.help{font-size:12px;color:#998579;line-height:1.7}.submit{width:100%;border:0;border-radius:14px;padding:17px;background:#bd7250;color:white;font-weight:700}.submit:disabled{opacity:.5}.error{color:#b84634;font-size:13px}.notice{padding:14px;background:#fff1e7;border-radius:12px;font-size:13px;line-height:1.7}.history-heading,.inquiry-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.history-heading h2{font-size:15px}.history-heading button{border:0;background:#fff5ee;border-radius:9px;padding:9px;color:#a86548}.history article{padding:24px 0;border-bottom:1px solid #eee}.inquiry-heading{font-size:14px}.inquiry-heading span{font-size:11px;color:#b47453}.history time{display:block;font-size:11px;color:#a19489;margin-top:8px}.question,.reply p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font-size:14px}.reply{padding:18px;background:#fff4eb;border-radius:14px}.reply strong{font-size:12px;color:#ae6949}.empty{padding:70px 0;text-align:center;color:#9c8d81}footer{padding-top:36px;color:#9c8c80;font-size:12px}footer details{border-top:1px solid #f0e9e3;padding:16px 0}footer p{font-size:11px;margin-top:20px}
</style>